import { theme, navigateTo } from '@atlantis/shared';
import { createT } from '@atlantis/i18n';
import type { TFunction } from '@atlantis/i18n';
import SHELL_KEYS from '../translations';
import { cachedFetch } from './cachedFetch';

// Lisbon coordinates (free, no API key needed)
const LAT = 38.7223;
const LON = -9.1393;

interface WeatherData {
  current: {
    temperature_2m: number;
    apparent_temperature: number;
    relative_humidity_2m: number;
    weather_code: number;
    wind_speed_10m: number;
    is_day: number;
  };
  daily: {
    temperature_2m_max: number[];
    temperature_2m_min: number[];
    sunrise: string[];
    sunset: string[];
    uv_index_max: number[];
  };
}

const WMO_ICONS: Record<number, string> = {
  0: '☀️', 1: '🌤️', 2: '⛅', 3: '☁️',
  45: '🌫️', 48: '🌫️',
  51: '🌦️', 53: '🌦️', 55: '🌧️',
  61: '🌧️', 63: '🌧️', 65: '🌧️',
  71: '🌨️', 73: '🌨️', 75: '🌨️', 77: '🌨️',
  80: '🌦️', 81: '🌧️', 82: '🌧️',
  85: '🌨️', 86: '🌨️',
  95: '⛈️', 96: '⛈️', 99: '⛈️',
};

const WMO_ICONS_NIGHT: Record<number, string> = {
  0: '🌙', 1: '🌙', 2: '☁️', 3: '☁️',
};

const WMO_DESC_EN: Record<number, string> = {
  0: 'Clear sky', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast',
  45: 'Foggy', 48: 'Rime fog',
  51: 'Light drizzle', 53: 'Drizzle', 55: 'Dense drizzle',
  61: 'Light rain', 63: 'Rain', 65: 'Heavy rain',
  71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 77: 'Snow grains',
  80: 'Light showers', 81: 'Showers', 82: 'Heavy showers',
  85: 'Light snow showers', 86: 'Snow showers',
  95: 'Thunderstorm', 96: 'Hail storm', 99: 'Severe hail storm',
};

const WMO_DESC_PT: Record<number, string> = {
  0: 'Céu limpo', 1: 'Pouco nublado', 2: 'Parcialmente nublado', 3: 'Encoberto',
  45: 'Nevoeiro', 48: 'Nevoeiro gelado',
  51: 'Chuviscos leves', 53: 'Chuviscos', 55: 'Chuviscos densos',
  61: 'Chuva fraca', 63: 'Chuva', 65: 'Chuva forte',
  71: 'Neve fraca', 73: 'Neve', 75: 'Neve forte', 77: 'Grãos de neve',
  80: 'Aguaceiros fracos', 81: 'Aguaceiros', 82: 'Aguaceiros fortes',
  85: 'Neve fraca', 86: 'Neve forte',
  95: 'Trovoada', 96: 'Granizo', 99: 'Granizo forte',
};

function getWeatherIcon(code: number, isDay: boolean): string {
  if (!isDay && code in WMO_ICONS_NIGHT) return WMO_ICONS_NIGHT[code];
  return WMO_ICONS[code] ?? '🌡️';
}

function getWeatherDesc(code: number, locale: string): string {
  const table = locale === 'pt' ? WMO_DESC_PT : WMO_DESC_EN;
  return table[code] ?? (locale === 'pt' ? 'Desconhecido' : 'Unknown');
}

// Accent tint that matches the vibe — warm sun, cool cloud, deep night.
// Used as a subtle glow behind the icon — doesn't flood the card.
function getAccent(code: number, isDay: boolean): string {
  if (!isDay) {
    if (code >= 95) return '#a78bfa';
    if (code >= 51) return '#60a5fa';
    return '#818cf8';
  }
  if (code === 0) return '#fbbf24';
  if (code === 1) return '#fcd34d';
  if (code === 2) return '#60a5fa';
  if (code === 3) return '#94a3b8';
  if (code >= 95) return '#c084fc';
  if (code >= 51) return '#38bdf8';
  if (code >= 45) return '#cbd5e1';
  return '#60a5fa';
}

function formatTime(iso: string, locale: string): string {
  const d = new Date(iso);
  return d.toLocaleTimeString(locale === 'pt' ? 'pt-PT' : 'en-GB', {
    hour: '2-digit', minute: '2-digit',
  });
}

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
`;

const float = keyframes`
  0%, 100% { transform: translateY(0) rotate(-2deg); }
  50% { transform: translateY(-6px) rotate(2deg); }
`;

const auroraPulse = keyframes`
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 0.85; transform: scale(1.08); }
`;

