interface WeatherWidgetProps {
  locale: string;
}

export function WeatherWidget({ locale }: WeatherWidgetProps) {
  const t: TFunction = useMemo(() => createT(locale === 'pt' ? 'pt' : 'en', SHELL_KEYS), [locale]);
  const [data, setData] = useState<WeatherData | null>(null);

  const fetchWeather = useCallback(async () => {
    const url =
      `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}` +
      `&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,is_day` +
      `&daily=temperature_2m_max,temperature_2m_min,sunrise,sunset,uv_index_max` +
      `&timezone=auto&forecast_days=2`;
    const result = await cachedFetch<WeatherData>(url, 'weather-lisbon-v3');
    if (result) setData(result);
  }, []);

  useEffect(() => {
    fetchWeather();
    const id = setInterval(fetchWeather, 15 * 60 * 1000);
    return () => clearInterval(id);
  }, [fetchWeather]);

  const openInEarth = () => navigateTo('earth', { placeId: 'lisbon' });
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openInEarth(); }
  };

  if (!data || !data.current || !data.daily) {
    return (
      <Wrapper role="link" tabIndex={0} onClick={openInEarth} onKeyDown={onKeyDown}>
        <Placeholder>{t('loading')}</Placeholder>
      </Wrapper>
    );
  }

  const { temperature_2m, apparent_temperature, relative_humidity_2m, weather_code, wind_speed_10m, is_day } = data.current;
  const isDay = is_day === 1;
  const accent = getAccent(weather_code, isDay);

  const todayMax = Math.round(data.daily.temperature_2m_max?.[0] ?? temperature_2m);
  const todayMin = Math.round(data.daily.temperature_2m_min?.[0] ?? temperature_2m);
  const uv = Math.round(data.daily.uv_index_max?.[0] ?? 0);
  const sunrise = data.daily.sunrise?.[0];
  const sunset = data.daily.sunset?.[0];
  const sunsetMs = sunset ? new Date(sunset).getTime() : NaN;
  const sunEvent = Number.isFinite(sunsetMs) && Date.now() < sunsetMs ? 'sunset' : 'sunrise';
  const sunTime = sunEvent === 'sunset' ? sunset : (data.daily.sunrise?.[1] ?? sunrise);

  return (
    <Wrapper role="link" tabIndex={0} onClick={openInEarth} onKeyDown={onKeyDown}>
      <TopBar>
        <Location>🌤️ {t('weather.city.lisbon')}</Location>
        <OpenHint>{t('weather.openInEarth')}</OpenHint>
      </TopBar>

      <Hero>
        <IconWrap accent={accent}>
          <BigIcon>{getWeatherIcon(weather_code, isDay)}</BigIcon>
        </IconWrap>
        <TempGroup>
          <TempRow>
            <Temp accent={accent}>{Math.round(temperature_2m)}°</Temp>
            <MinMax>
              <div>▲ <span>{todayMax}°</span></div>
              <div>▼ <span>{todayMin}°</span></div>
            </MinMax>
          </TempRow>
          <Condition>{getWeatherDesc(weather_code, locale)}</Condition>
          <FeelsLike>{t('weather.feelsLike', { t: Math.round(apparent_temperature) })}</FeelsLike>
        </TempGroup>
      </Hero>

      <StatsRow>
        <StatPill>
          <StatLabel>💧 {t('weather.humidity')}</StatLabel>
          <StatValue>{relative_humidity_2m}%</StatValue>
        </StatPill>
        <StatPill>
          <StatLabel>💨 {t('weather.wind')}</StatLabel>
          <StatValue>{Math.round(wind_speed_10m)} km/h</StatValue>
        </StatPill>
        <StatPill>
          <StatLabel>☀️ {t('weather.uv')}</StatLabel>
          <StatValue>{uv}</StatValue>
        </StatPill>
        <StatPill>
          <StatLabel>{sunEvent === 'sunset' ? '🌇' : '🌅'} {t(sunEvent === 'sunset' ? 'weather.sunset' : 'weather.sunrise')}</StatLabel>
          <StatValue>{sunTime ? formatTime(sunTime, locale) : '—'}</StatValue>
        </StatPill>
      </StatsRow>
    </Wrapper>
  );
}
