import { putSetting, getSetting } from './db';

export const DAILY_PROGRESS_KEY = 'daily:progress';

export interface DailyMission {
  id: string;
  emoji: string;
  nameEn: string;
  namePt: string;
  points: number;
}

export interface DailyProgress {
  totalPoints: number;
  totalMissionsCompleted: number;
  completedToday: string[];
  streakDays: string[];
  lastResetDate: string;
  missions: DailyMission[];
  /**
   * Per-day completion log. Keys are YYYY-MM-DD, values are the mission ids
   * that were checked off that day. The record is the canonical source for
   * week/month analytics; `completedToday` and `streakDays` are convenience
   * projections kept in sync for the current UI.
   */
  history: Record<string, string[]>;
}

export function todayISO(): string {
  return new Date().toISOString().slice(0, 10);
}

export function computeDailyStreak(streakDays: string[]): number {
  if (streakDays.length === 0) return 0;
  const sorted = [...new Set(streakDays)].sort().reverse();
  const today = todayISO();
  let streak = 0;
  let expected = today;
  for (const day of sorted) {
    if (day === expected) {
      streak++;
      const d = new Date(expected);
      d.setDate(d.getDate() - 1);
      expected = d.toISOString().slice(0, 10);
    } else {
      break;
    }
  }
  return streak;
}

export async function loadDailyProgress(): Promise<DailyProgress | null> {
  try {
    const raw = await getSetting(DAILY_PROGRESS_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as DailyProgress;
  } catch {
    return null;
  }
}

export const DAILY_PROGRESS_EVENT = 'atlantis:daily-progress-change';

/** Returns YYYY-MM-DD keys for the last N days ending today (inclusive), oldest first. */
export function lastNDays(n: number, from: Date = new Date()): string[] {
  const out: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(from);
    d.setDate(d.getDate() - i);
    out.push(d.toISOString().slice(0, 10));
  }
  return out;
}

export interface DayStat {
  date: string;            // YYYY-MM-DD
  completedIds: string[];  // mission ids done that day
  count: number;
}

/** Pulls N recent days from history, filling missing days with empty arrays. */
export function getDailyHistory(progress: DailyProgress, days: number): DayStat[] {
  return lastNDays(days).map((date) => {
    const ids = progress.history[date] ?? [];
    return { date, completedIds: ids, count: ids.length };
  });
}

/** True when the given mission was completed on the given YYYY-MM-DD. */
export function wasMissionDone(progress: DailyProgress, missionId: string, date: string): boolean {
  return progress.history[date]?.includes(missionId) ?? false;
}

export async function saveDailyProgress(progress: DailyProgress): Promise<void> {
  try {
    await putSetting(DAILY_PROGRESS_KEY, JSON.stringify(progress));
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent<DailyProgress>(DAILY_PROGRESS_EVENT, { detail: progress }));
    }
  } catch {
    // ignore — non-fatal
  }
}
