// ─── Remote registry ────────────────────────────────────────────────────────
//
// Adding a new remote = one entry here + one entry in `apps.config.yml` + one
// module declaration in `declarations.d.ts`. The render loop below picks the
// component up by id automatically.

type RemoteComponent = React.LazyExoticComponent<
  React.ComponentType<{ topBarRight?: React.ReactNode; [extra: string]: unknown }>
>;

const REMOTES: Record<string, RemoteComponent> = {
  markdown:     React.lazy(() => import('markdown/App')),
  earth:        React.lazy(() => import('earth/App')),
  techscope:    React.lazy(() => import('techscope/App')),
  citypulse:    React.lazy(() => import('citypulse/App')),
  cosmos:       React.lazy(() => import('cosmos/App')),
  stockpulse:   React.lazy(() => import('stockpulse/App')),
  pad:          React.lazy(() => import('pad/App')),
  regexlab:     React.lazy(() => import('regexlab/App')),
  jsonexplorer: React.lazy(() => import('jsonexplorer/App')),
  codediff:     React.lazy(() => import('codediff/App')),
  playground:   React.lazy(() => import('playground/App')),
  jwtinspector: React.lazy(() => import('jwtinspector/App')),
  colorlab:     React.lazy(() => import('colorlab/App')),
  cronbuilder:  React.lazy(() => import('cronbuilder/App')),
  csvexplorer:  React.lazy(() => import('csvexplorer/App')),
  chartbuilder: React.lazy(() => import('chartbuilder/App')),
  school:       React.lazy(() => import('school/App')),
  weather:      React.lazy(() => import('weather/App')),
  apiexplorer:  React.lazy(() => import('apiexplorer/App')),
  movies:       React.lazy(() => import('movies/App')),
  promptlab:    React.lazy(() => import('promptlab/App')),
  imagegen:     React.lazy(() => import('imagegen/App')),
  games:        React.lazy(() => import('games/App')),
  daily:        React.lazy(() => import('daily/App')),
};

// ─── Extra props for specific apps ──────────────────────────────────────────
//
// Most remotes only receive `topBarRight`. A couple need extra props — declare
// their contract here, next to the registry, so the "what does Movies need?"
// question has one authoritative answer.

interface RenderContext {
  user: User | null;
  tmdbKey: string;
}

const EXTRA_PROPS: Partial<Record<string, (ctx: RenderContext) => Record<string, unknown>>> = {
  movies: (ctx) => ({ apiKey: ctx.tmdbKey }),
  games:  (ctx) => ({ isAuthenticated: !!ctx.user }),
};

// Dev-time drift check: every `apps.config.yml` entry must have a matching
// REMOTES key. Webpack Module Federation requires `import('id/App')` to be a
// literal string, so REMOTES can't be generated from YAML at runtime — but we
// can at least fail loudly when the two drift out of sync.
if (process.env.NODE_ENV !== 'production') {
  const missing = APP_CONFIG
    .filter((a) => a.enabled)
    .map((a) => a.id)
    .filter((id) => !REMOTES[id]);
  if (missing.length) {
    // eslint-disable-next-line no-console
    console.error(
      `[shell] apps.config.yml lists ${missing.join(', ')} but App.tsx REMOTES has no entry. ` +
        `Add a React.lazy() line (plus a module declaration in declarations.d.ts).`,
    );
  }
  const stale = Object.keys(REMOTES).filter(
    (id) => !APP_CONFIG.some((a) => a.id === id),
  );
  if (stale.length) {
    // eslint-disable-next-line no-console
    console.warn(
      `[shell] REMOTES contains ${stale.join(', ')} but apps.config.yml doesn't list them. ` +
        `Remove the lazy import or re-add the config entry.`,
    );
  }
}

